-- public.rock_raise_refusal(p_world uuid, p_uid uuid, cx integer, cy integer, p_what text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.rock_raise_refusal(p_world uuid, p_uid uuid, cx integer, cy integer, p_what text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare v_deep double precision; v_under text;
begin
  if land_dirt(p_world, cx, cy) > 0 then return 'Soil on that corner. ' || p_what || ' needs bare rock.'; end if;
  v_deep := pk(p_world, p_uid, 'depth:raise_rock', 0);
  if land_height(p_world, cx, cy) < -v_deep then
    return case when v_deep > 0 then p_what || ': not under more than ' || metres(v_deep) || ' m of water.'
                else p_what || ': not under water.' end;
  end if;
  -- And never on a seam. A corner holds up four tiles, and a vein under any
  -- of them raised with concrete would be ore for ever: mined down, laid up
  -- and mined again.
  if exists (select 1 from (values (cx - 1, cy - 1), (cx, cy - 1), (cx - 1, cy), (cx, cy)) v(x, y)
             where in_bounds(p_world, v.x, v.y) and (bedrock_at(p_world, v.x, v.y)).seam) then
    return 'Corner on a seam. ' || p_what || ' needs plain rock.';
  end if;
  v_under := corner_under_building(p_world, cx, cy);
  if v_under is not null then return v_under; end if;
  return coalesce(level_stop(p_world, p_uid, cx, cy, 1),
                  slope_refusal(p_world, p_uid, 'masonry', cx, cy, 1));
end $function$
